-- ============================================================
-- Rhesys - Palavras-chave ampliadas (termos de busca)
-- ------------------------------------------------------------
-- Amplia as palavras-chave de TODOS os resíduos com sinônimos, nomes
-- populares, marcas e exemplos do dia a dia, para a pessoa encontrar o
-- resíduo digitando do jeito que fala ("remédio", "latinha", "durex"...).
-- Também aumenta a coluna palavras_chave para caber as listas maiores.
--
-- Script IDEMPOTENTE. Execute depois de todos os lotes de resíduos:
--   mysql -u root -p < database/palavras_chave_ampliadas.sql
-- ============================================================
USE rhesys;

ALTER TABLE residuo MODIFY palavras_chave VARCHAR(1000) NULL;

